#!/usr/bin/env python3
# Exact-integer fail-closed verifier for lemma L3, contract 33024e452a491159.
# Entry point: verify(witness) -- raises on ANY failed check; returns True on PASS.
# Exhaustive enumeration over all subsets of {0..N}, N in 0..6. Ints only;
# deterministic; no network; no filesystem; no I/O.
from itertools import combinations

def covers(A, N):
    d = set()
    for a in A:
        for b in A:
            d.add(a - b if a >= b else b - a)
    for x in range(0, N + 1):
        if x not in d:
            return False
    return True

def counting_lb(N):
    k = 1
    while k * (k + 1) // 2 < N + 1:
        k += 1
    return k

def verify(witness):
    expected_F = {int(k): v for k, v in witness["expected_F"].items()}
    ties = frozenset(witness["expected_ties"])
    strict = frozenset(witness["expected_strict"])
    extremizers = {int(k): [tuple(x) for x in v]
                   for k, v in witness["certified_extremizers"].items()}
    for N in range(0, 7):
        universe = list(range(0, N + 1))
        f = None
        for k in range(1, N + 2):
            found = False
            for A in combinations(universe, k):
                if covers(A, N):
                    f = k
                    found = True
                    break
            if found:
                break
        if f is None or f != expected_F[N]:
            raise AssertionError("F(%d) mismatch" % N)
        lb = counting_lb(N)
        if N in ties and f != lb:
            raise AssertionError("N=%d tie violated" % N)
        if N in strict and f <= lb:
            raise AssertionError("N=%d strict violated" % N)
        if (N in ties) == (N in strict):
            raise AssertionError("N=%d unclassified" % N)
        allE = set()
        for C in combinations(universe, f):
            if covers(C, N):
                allE.add(C)
        if N in extremizers:
            if not extremizers[N]:
                raise AssertionError("no extremizer at N=%d" % N)
            for e in extremizers[N]:
                if e not in allE:
                    raise AssertionError("bogus extremizer at N=%d" % N)
    return True

WITNESS = {
 "expected_F": {"0": 1, "1": 2, "2": 3, "3": 3, "4": 4, "5": 4, "6": 4},
 "expected_ties": [0, 1, 3, 6],
 "expected_strict": [2, 4, 5],
 "certified_extremizers": {
  "0": [[0]], "1": [[0, 1]], "3": [[0, 1, 3]], "6": [[0, 1, 4, 6]]
 }
}

verify(WITNESS)
